    EXECUTE 'GRANT MAINTAIN ON TABLE public."training_sessions" TO anon';
  END IF;

  -- ---------------------------------------------------------------- 2. the 19 policies → TO public (roles only)
  ALTER POLICY "leaders can read action_items" ON public."action_items" TO public;
  ALTER POLICY "leaders can read ai_feedback" ON public."ai_feedback" TO public;
  ALTER POLICY "dept reads ai_outputs" ON public."ai_outputs" TO public;
  ALTER POLICY "Leaders read all certs" ON public."certs" TO public;
  ALTER POLICY "authenticated can read content_calendar" ON public."content_calendar" TO public;
  ALTER POLICY "authenticated can read documents" ON public."documents" TO public;
  ALTER POLICY "authenticated can read duties" ON public."duties" TO public;
  ALTER POLICY "da or manager manage equipment" ON public."equipment" TO public;
  ALTER POLICY "members read equipment" ON public."equipment" TO public;
  ALTER POLICY "da or manager manage equipment photos" ON public."equipment_photos" TO public;
  ALTER POLICY "members read equipment photos" ON public."equipment_photos" TO public;
  ALTER POLICY "da or manager manage equipment types" ON public."equipment_type" TO public;
  ALTER POLICY "members read equipment types" ON public."equipment_type" TO public;
  ALTER POLICY "authenticated can read events" ON public."events" TO public;
  ALTER POLICY "authenticated can read maintenance" ON public."maintenance" TO public;
  ALTER POLICY "leaders can read meetings" ON public."meetings" TO public;
  ALTER POLICY "leaders read members base table" ON public."members" TO public;
  ALTER POLICY "leaders can read onboarding_progress" ON public."onboarding_progress" TO public;
  ALTER POLICY "authenticated can read training_sessions" ON public."training_sessions" TO public;

  -- ---------------------------------------------------------------- 3. the defaults, as captured
  ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES TO anon;
  ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO anon;
  ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO anon;
  ALTER DEFAULT PRIVILEGES FOR ROLE postgres GRANT EXECUTE ON FUNCTIONS TO PUBLIC;

  -- ---------------------------------------------------------------- 4. post-conditions (in-transaction)

    v_after := '{}'::jsonb;
    FOR d IN SELECT id FROM public.departments ORDER BY id LOOP
      FOR v_who IN SELECT unnest(ARRAY['DA', 'member']) LOOP
        IF v_who = 'DA' THEN SELECT lower(m.email) FROM public.members m WHERE m.department_id = d AND m.status IN ('Active', 'Probationary') AND m.access && array['Department Admin']::text[]
          AND m.email IS NOT NULL AND (SELECT count(*) FROM public.members x WHERE lower(x.email) = lower(m.email)) = 1
          AND NOT EXISTS (SELECT 1 FROM public.member_separation s WHERE s.member_id = m.id) ORDER BY m.id LIMIT 1 INTO v_email; ELSE SELECT lower(m.email) FROM public.members m WHERE m.department_id = d AND m.status = 'Active' AND NOT (coalesce(m.access, '{}') && array['Project Admin', 'Department Admin', 'Board Member', 'Officer']::text[])
          AND m.email IS NOT NULL AND (SELECT count(*) FROM public.members x WHERE lower(x.email) = lower(m.email)) = 1
          AND NOT EXISTS (SELECT 1 FROM public.member_separation s WHERE s.member_id = m.id) ORDER BY m.id LIMIT 1 INTO v_email; END IF;
        IF v_email IS NULL THEN v_after := v_after || jsonb_build_object(d::text || '|' || v_who, 'no such member'); CONTINUE; END IF;
        PERFORM set_config('request.jwt.claims', json_build_object('email', v_email)::text, true);
        EXECUTE 'SET LOCAL ROLE authenticated';
        FOREACH v_rel IN ARRAY c_rels LOOP
          BEGIN EXECUTE format('SELECT count(*)::text FROM public.%I', v_rel) INTO v_val;
          EXCEPTION WHEN OTHERS THEN v_val := 'E:' || SQLSTATE; END;
          v_after := v_after || jsonb_build_object(d::text || '|' || v_who || '|' || v_rel, v_val);
        END LOOP;
        EXECUTE 'RESET ROLE';
      END LOOP;
    END LOOP;
    PERFORM set_config('request.jwt.claims', '', true);
  IF v_after IS DISTINCT FROM v_before THEN
    SELECT string_agg(k || ' ' || (v_before->>k) || '->' || coalesce(v_after->>k, '?'), '; ') INTO v_t
      FROM (SELECT k FROM jsonb_object_keys(v_before) k WHERE (v_before->>k) IS DISTINCT FROM (v_after->>k) LIMIT 5) z;
    RAISE EXCEPTION 'Post-condition failed: a real member''s or DA''s row counts changed: %. Rolling back.', v_t;
  END IF;
  IF v_pg17 THEN
    EXECUTE $q$
    SELECT coalesce(jsonb_object_agg(x.rel, x.privs), '{}'::jsonb) FROM (
      SELECT c.relname AS rel, string_agg(a.privilege_type, ',' ORDER BY a.privilege_type) AS privs
        FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
       WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND a.grantee = 'anon'::regrole
       GROUP BY c.relname) x$q$ INTO v_after;
    IF v_after IS DISTINCT FROM c_anon_full THEN RAISE EXCEPTION 'Post-condition failed: anon''s grants are not the captured set. Rolling back.'; END IF;
  ELSE
    EXECUTE $q$
    SELECT coalesce(jsonb_object_agg(x.rel, x.privs), '{}'::jsonb) FROM (
      SELECT c.relname AS rel, string_agg(a.privilege_type, ',' ORDER BY a.privilege_type) AS privs
        FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
       WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND a.grantee = 'anon'::regrole
         AND a.privilege_type <> 'MAINTAIN'
       GROUP BY c.relname) x$q$ INTO v_after;
    IF v_after IS DISTINCT FROM c_anon THEN RAISE EXCEPTION 'Post-condition failed: anon''s grants are not the captured set. Rolling back.'; END IF;
  END IF;
  FOR r IN SELECT * FROM (VALUES
      ('action_items', 'leaders can read action_items', 'fb0895d133d5c4f27e407a628e517f7b', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('ai_feedback', 'leaders can read ai_feedback', '2226e4850f341e4cca8e54f6a40b7c48', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('ai_outputs', 'dept reads ai_outputs', '7e881c6dcccbf5819f46285ed35d4519', 'faa12de96e5e67a68845806bddedfb23'),
      ('certs', 'Leaders read all certs', 'c8d594221ad7249b27e5530836f1a46f', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('content_calendar', 'authenticated can read content_calendar', '76adc646fd3e42ce6b2848082121bc1b', 'faa12de96e5e67a68845806bddedfb23'),
      ('documents', 'authenticated can read documents', '65cd0ced16ade6788d756e39d076108b', 'faa12de96e5e67a68845806bddedfb23'),
      ('duties', 'authenticated can read duties', '6e6ed65eaaee0b9bc2bb11be5b4feeac', 'faa12de96e5e67a68845806bddedfb23'),
      ('equipment', 'da or manager manage equipment', '222b2a75b0c5716a6436a5de0fe2150e', 'bccc49398c78eab7a46089dfe756d6b0'),
      ('equipment', 'members read equipment', 'e6b10bbc3375823e5045c90110048891', 'faa12de96e5e67a68845806bddedfb23'),
      ('equipment_photos', 'da or manager manage equipment photos', '191d8255342dc0489aa957db734154e6', 'bccc49398c78eab7a46089dfe756d6b0'),
      ('equipment_photos', 'members read equipment photos', 'fcf3f1a55fa6d2b1d4a3b9d78782cca2', 'faa12de96e5e67a68845806bddedfb23'),
      ('equipment_type', 'da or manager manage equipment types', '966a116b301f3f64fadf1487f1190f53', 'bccc49398c78eab7a46089dfe756d6b0'),
      ('equipment_type', 'members read equipment types', '3870668e5cecb05d129fb2f2b85c1663', 'faa12de96e5e67a68845806bddedfb23'),
      ('events', 'authenticated can read events', 'a5ca268f581a0c7fafab99517b71948d', 'faa12de96e5e67a68845806bddedfb23'),
      ('maintenance', 'authenticated can read maintenance', '6aedc8f31a35bdf0271c9f5851f7859b', 'faa12de96e5e67a68845806bddedfb23'),
      ('meetings', 'leaders can read meetings', '03cbac40664a7b34d26d2da57c7f061c', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('members', 'leaders read members base table', '98393de0953d2ae84ae90c75576a6af5', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('onboarding_progress', 'leaders can read onboarding_progress', 'a8c4de2c41df0e3ada826362bfb33507', '6bc7e77ed4ffcc0986bf2545eb3180c1'),
      ('training_sessions', 'authenticated can read training_sessions', '8421473009c6a890befb4f8e5011c7a6', 'faa12de96e5e67a68845806bddedfb23')) v(tbl, name, md5, pred) LOOP
    SELECT md5(p.tablename || '|' || p.policyname || '|' || p.cmd || '|' || p.permissive || '|' || p.roles::text || '|' || coalesce(p.qual, '') || '|' || coalesce(p.with_check, '')) INTO v_t FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = r.tbl AND p.policyname = r.name;
    IF v_t IS DISTINCT FROM r.md5 THEN RAISE EXCEPTION 'Post-condition failed: policy "%" on % is not back to its original definition. Rolling back.', r.name, r.tbl; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND roles = '{public}'::name[]) <> 19 THEN
    RAISE EXCEPTION 'Post-condition failed: expected exactly 19 {public} policies. Rolling back.';
  END IF;
  EXECUTE $q$
    SELECT md5(string_agg(c.relname || ':' || a.privilege_type, ',' ORDER BY c.relname, a.privilege_type))
      FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
     WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND a.grantee = 'authenticated'::regrole$q$ INTO v_t;
  IF v_t IS DISTINCT FROM c_auth_md5 THEN RAISE EXCEPTION 'Post-condition failed: authenticated''s privileges changed. Rolling back.'; END IF;
  EXECUTE $q$
    SELECT md5(string_agg(c.relname || ':' || a.privilege_type, ',' ORDER BY c.relname, a.privilege_type))
      FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
     WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND a.grantee = 'service_role'::regrole$q$ INTO v_t;
  IF v_t IS DISTINCT FROM c_svc_md5 THEN RAISE EXCEPTION 'Post-condition failed: service_role''s privileges changed. Rolling back.'; END IF;
  FOR r IN SELECT k AS t, c_defaults->>k AS acl FROM jsonb_object_keys(c_defaults) k LOOP
    IF (SELECT string_agg(x::text, ',' ORDER BY x::text) FROM unnest((SELECT d.defaclacl FROM pg_default_acl d WHERE d.defaclrole = 'postgres'::regrole AND d.defaclnamespace = 'public'::regnamespace AND d.defaclobjtype::text = r.t)) x)
       IS DISTINCT FROM (SELECT string_agg(x::text, ',' ORDER BY x::text) FROM unnest(r.acl::aclitem[]) x) THEN
      RAISE EXCEPTION 'Post-condition failed: postgres''s public default for % is not the captured set. Rolling back.', r.t;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_default_acl d WHERE d.defaclrole = 'postgres'::regrole AND d.defaclnamespace = 0) THEN
    RAISE EXCEPTION 'Post-condition failed: a global postgres default is left (the capture had none). Rolling back.';
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE schemaname = 'public') <> v_pol_before
     OR (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f') <> v_fn_before THEN
    RAISE EXCEPTION 'Post-condition failed: the policy or function count changed. Rolling back.';
  END IF;
  SELECT count(*) INTO v_ver_after FROM public.station_presence WHERE verified;
  IF v_ver_after <> v_ver_before THEN RAISE EXCEPTION 'Post-condition failed: verified presence changed (% -> %). Rolling back.', v_ver_before, v_ver_after; END IF;
END
$rollback$;

NOTIFY pgrst, 'reload schema';

SELECT jsonb_build_object(
  'anon_acl_entries',     (SELECT count(*) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND a.grantee = 'anon'::regrole),
  'public_role_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND roles = '{public}'::name[]),
  'default_acl_postgres', (SELECT jsonb_object_agg(CASE WHEN d.defaclnamespace = 0 THEN '(global)' ELSE d.defaclnamespace::regnamespace::text END || ':' || d.defaclobjtype::text, d.defaclacl::text) FROM pg_default_acl d WHERE d.defaclrole = 'postgres'::regrole AND (d.defaclnamespace = 0 OR d.defaclnamespace = 'public'::regnamespace)),
  'total_policies',       (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'fn_count',             (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'verified_presence',    (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
